_FC_BLEND = np.asarray([[0.9812061190605164, 0.06251616030931473], [-0.03448789194226265, 0.9482923150062561], [0.0521344318985939, 0.07075505703687668], [0.0995580181479454, -0.07501468807458878], [-0.18795974552631378, -0.21407246589660645], [0.14550799131393433, 0.21865028142929077], [-0.09615086764097214, 0.020749101415276527], [0.009588446468114853, -0.09268150478601456], [0.07874228805303574, 0.09861551225185394]])
